import 'fake-indexeddb/auto';
import {ScopedEditorStore} from '../src/sync/editorStore';
import {applyNativeOperation} from '../src/sync/server';
import {it,expect} from 'vitest';
import {readFileSync,writeFileSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
import {newId} from '../src/domain/model';
import type {ProjectData} from '../src/domain/types';
import {bootstrapNativeProject,type AtomicSyncRepository,type ServerIdentity} from '../src/sync/server';
import {applyEditorOperation,readEditorImage} from '../src/sync/editor';
import {createSyncOperation,type SyncOperation} from '../src/sync/protocol';
import {assertAck} from '../src/sync/validation';
const root='/tmp/shinariokanri-independent-rb09-cfaebcb/independent',container='shinariokanri-independent-rb09-cfaebcb',owner:ServerIdentity={accountId:'00000000-0000-4000-8000-000000000001',sessionId:'10000000-0000-4000-8000-000000000001'},editor:ServerIdentity={accountId:'00000000-0000-4000-8000-000000000002',sessionId:'10000000-0000-4000-8000-000000000002'},calls:unknown[]=[];
function arg(v:unknown):string{if(v===null)return'null';if(v&&typeof v==='object'&&'rawSQL'in v)return(v as {rawSQL:string}).rawSQL;return"'"+(typeof v==='object'?JSON.stringify(v):String(v)).replace(/'/g,"''")+"'"+(typeof v==='object'?'::jsonb':'');}
function sql(text:string){const r=spawnSync('docker',['exec','-i',container,'psql','-U','postgres','-qAt','-v','ON_ERROR_STOP=1'],{input:text,encoding:'utf8',timeout:20000,maxBuffer:32*1024*1024});calls.push({sql:text,status:r.status,stdout:r.stdout,stderr:r.stderr});writeFileSync(root+'/sql-expiry-renewal-calls.json',JSON.stringify(calls,null,2)+'\n');if(r.status!==0)throw Error(r.stderr||'SQL_CALL_FAILED');return r.stdout;}
function rpc(name:string,values:unknown[]){const out=sql('set role service_role;\nselect public.'+name+'('+values.map(arg).join(',')+')::text;\n').trim();return out?JSON.parse(out):null;}
const repository:AtomicSyncRepository={read:async(i,p,b,o)=>rpc('scenario_sync_engine_context',[i.accountId,i.sessionId,p,b,o]),bootstrap:async(i,v)=>rpc('scenario_sync_bootstrap',[i.accountId,i.sessionId,v.project.projectId,v.project,v.documents,v.worlds]),commit:async(i,v)=>rpc('scenario_sync_commit_prepared',[i.accountId,i.sessionId,v.projectId,v.expectedRevision,v.operation,v.operationHash,v.ack,v.documents,v.image,{rawSQL:'ARRAY['+(v.derivedIds??[]).map(id=>"'"+id+"'").join(',')+']::uuid[]'}])};
function proof(id:string,data:unknown){writeFileSync(root+'/fixtures/'+id+'.json',JSON.stringify(data,null,2)+'\n');}
async function seed(){const f=JSON.parse(readFileSync(root+'/fixtures/native-two-targets.json','utf8')) as {p:ProjectData;idA:string;idB:string};f.p.projectId=newId();f.p.entities.forEach(e=>e.projectId=f.p.projectId);const a=f.p.entities.find(e=>e.id===f.idA)!;a.customValues['private-editor-canary']='PRIVATE_GRANTED_DOC_FIELD';const b=f.p.entities.find(e=>e.id===f.idB)!;b.visibility='private';b.name='PRIVATE_EDITOR_RECORD_CANARY';await bootstrapNativeProject(repository,owner,{project:f.p,worlds:{}});rpc('scenario_membership',[owner.accountId,owner.sessionId,f.p.projectId,editor.accountId,'editor',null,false,{rawSQL:'array[]::uuid[]'},0]);rpc('scenario_editor_grants',[owner.accountId,owner.sessionId,f.p.projectId,editor.accountId,[{id:f.idA,fields:['name']}],1,1]);return f;}
async function rename(f:Awaited<ReturnType<typeof seed>>,name='許可された編集😀'):Promise<SyncOperation>{const image=await readEditorImage(repository,editor,f.p.projectId),base=image.documents[0],local=structuredClone(base);local.fields.name=name;return createSyncOperation({scope:{accountId:editor.accountId,projectId:f.p.projectId},baseRevision:image.serverRevision,operationId:newId(),targets:[{base,local}]});}
it('R9SQL-expiry-current an applied ACK at content2/auth2 before finite B expiry must not replace the freshly read same-content/auth A-only null-expiry descriptor; A edit is allowed',async()=>{
 const f=JSON.parse(readFileSync(root+'/fixtures/native-two-targets.json','utf8')) as {p:ProjectData;idA:string;idB:string};f.p.projectId=newId();f.p.entities.forEach(e=>e.projectId=f.p.projectId);await bootstrapNativeProject(repository,owner,{project:f.p,worlds:{}});rpc('scenario_membership',[owner.accountId,owner.sessionId,f.p.projectId,editor.accountId,'editor',null,false,{rawSQL:'array[]::uuid[]'},0]);rpc('scenario_editor_grants',[owner.accountId,owner.sessionId,f.p.projectId,editor.accountId,[{id:f.idA,fields:['name']},{id:f.idB,fields:['name']}],1,1]);
 const expiry=new Date(Date.now()+6000).toISOString();sql('update scenario_private.editor_scopes set expires_at='+arg(expiry)+'::timestamptz where project_id='+arg(f.p.projectId)+'::uuid and account_id='+arg(editor.accountId)+'::uuid and document_id='+arg(f.idB)+'::uuid;');
 const initial=await readEditorImage(repository,editor,f.p.projectId),cache=new ScopedEditorStore(editor.accountId);
 try{
  expect(initial.authorizationRevision).toBe('2');expect(initial.authorizationExpiresAt).not.toBeNull();expect(initial.documents.map(d=>d.id).sort()).toEqual([f.idA,f.idB].sort());await cache.receive(initial);await cache.saveField(f.p.projectId,f.idA,'name','期限前に確定したA');const op=(await cache.prepare(f.p.projectId))!,ack=await applyEditorOperation(repository,editor,op);expect(ack.status).toBe('applied');expect(ack.serverRevision).toBe('2');expect(ack.authorizationRevision).toBe('2');await cache.acknowledge(ack);
  await new Promise(resolve=>setTimeout(resolve,Math.max(0,Date.parse(expiry)-Date.now()+75)));const fresh=await readEditorImage(repository,editor,f.p.projectId);expect(fresh.serverRevision).toBe('2');expect(fresh.authorizationRevision).toBe('2');expect(fresh.authorizationExpiresAt).toBeNull();expect(fresh.documents.map(d=>d.id)).toEqual([f.idA]);await cache.receive(fresh);const before=await cache.get(f.p.projectId);let error;try{await cache.saveField(f.p.projectId,f.idA,'name','期限後も許可されたA');}catch(e){error=e;}const after=await cache.get(f.p.projectId);proof('R9SQL-expiry-current',{initial,ack,fresh,before,after,error:String(error),expected:'Fresh current A-only null-expiry descriptor permits A write; exact old ACK remains historical; real SQL passage of finite scope deadline does not increment membership revision',environment:'Own network-none PostgreSQL17.11 real typed RPCs, synthetic Auth/Storage, no live API'});expect(error).toBeUndefined();expect(after!.documents.find(d=>d.id===f.idA)!.fields.name).toBe('期限後も許可されたA');expect(after!.acks).toEqual(before!.acks);
 }finally{await cache.delete();}
});
